INSERT INTO `channel` VALUES (1,2,'货币专区','/product/index/channel_id/1',1,'/static/picture/5bff97ffcc002.png',1551342249,0,'限时发',NULL,0,0),(2,2,'理财热销推荐','/product/zq/channel_id/2',3,'/static/picture/5bff97ffcc002.png',1551342730,0,'标期灵活 | 多样选择',NULL,1,0),(3,2,'股权热销推荐','product/zq/channel_id/4',4,'/static/picture/5bff97ffcc002.png',1552788519,0,'股权专区',NULL,6,0),(5,1,'推广连接','/user/spread',2,'/static/picture/5bff97ffcc002.png',1551342901,0,'','<p>&nbsp; &nbsp;</p>',3,0),(6,2,'领取红包','/user/hongbao',2,'/static/picture/5bff97ffcc002.png',1551342932,0,'',NULL,2,0),(7,2,'幸运转盘','/user/welfare',2,'/static/picture/5bff97ffcc002.png',1551342974,0,'幸运大转盘',NULL,3,0),(8,2,'操作指南','/about/about',2,'/static/picture/5bff97ffcc002.png',1551343004,0,'','<p><span style=\"color: rgb(14, 23, 38); font-family: &quot;PingFang SC&quot;, -apple-system, BlinkMacSystemFont, Roboto, &quot;Helvetica Neue&quot;, Helvetica, Arial, &quot;Hiragino Sans GB&quot;, &quot;Source Han Sans&quot;, &quot;Noto Sans CJK Sc&quot;, &quot;Microsoft YaHei&quot;, &quot;Microsoft Jhenghei&quot;, sans-serif; font-size: 14px;\"><span style=\" background-color: rgb(255, 255, 255);\"><strong></strong></span></span></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p><span style=\"font-size: 18px;\">1.&nbsp;如何实名认证和绑定银行卡？</span></p><p><span style=\"font-size:18px;\">&nbsp;&nbsp;点击----我的----设置----实名认证----按照要求填写实名认证信息认证。</span></p><p><span style=\"font-size:18px;\">&nbsp;&nbsp;点击----我的----设置----我的银行卡----添加银行卡----按照要求正确填写银行卡信息（注意：银行卡名字和收款卡号必须是同一个人）----立即绑定。</span></p><p><span style=\"font-size:18px;\">&nbsp;</span></p><p><span style=\"font-size:18px;\">2.&nbsp;如何购买股权、基金、货币等理财产品？</span></p><p><span style=\"font-size:18px;\">&nbsp;&nbsp;点击APP下面的股权、理财、货币菜单选项，进入对应的股权、货币、基金专区进行购买。购买需要先核对你想要购买的数量和金额，再进行购买，购买金额和转账金额必须一致。</span></p><p><span style=\"font-size:18px;\">&nbsp;</span></p><p><span style=\"font-size:18px;\">3.&nbsp;如何完成付款？</span></p><p><span style=\"font-size:18px;\">&nbsp;&nbsp;付款方式有两种：</span></p><p><span style=\"font-size:18px;\">&nbsp;&nbsp;第一种：银行卡支付。点击立即购买，进入银行卡转账，按照APP上的收款账号，通过手机银行进行转账，或者通过支付宝转账到银行卡。转账完成后保存好正确的转账截图（转账凭证需要有收款人名字、收款人卡号以及转账时间，方便财务核实你的转账信息）转账完成后，再回到APP银行卡转账页面，点击摄像头图案，选择转账截图图片，上传转账凭证，等提交栏变成红色，图片上传成功，点击提交就可以了。订单提交后，会由审核部门负责订单审核，确认订单无误，审核通过后，你购买的产品就会到账。同一订单只需要提交一次，不用重复上传；</span></p><p><span style=\"font-size:18px;\">&nbsp;&nbsp;第二种：余额支付。选择你要购买的产品，支付方式选择余额支付，点击立即购买，输入支付密码，确认。付款成功就说明购买成功了。余额支付购买的产品立即到账，不用上传截图。注意：余额支付是指你在华夏云投账户的余额，余额来自于你的推荐佣金、股权和基金的每天返利。为了大家能够获得更大的收益，大家也可以用账户余额资金来进行股权和基金的复投，简单便捷。</span></p><p><span style=\"font-size:18px;\">&nbsp;</span></p><p><span style=\"font-size:18px;\">4.&nbsp;如何查看我购买的产品？</span></p><p><span style=\"font-size:18px;\">&nbsp;&nbsp;点击我的，在我的股权、我的理财和我的货币可以查看对应的产品。</span></p><p><span style=\"font-size:18px;\">&nbsp;</span></p><p><span style=\"font-size:18px;\">5.&nbsp;如何提现？</span></p><p><span style=\"font-size:18px;\">&nbsp;点击----我的---我的钱包---账户余额栏的资金是你可以提现的资金。点击提现----输入你要提现的金额---选择你要提交的银行卡，确定提现。提现申请提交后，会由财务进行审核，审核通过后你的提现资金即可到账。</span></p><p><span style=\"color: rgb(14, 23, 38); font-family: &quot;PingFang SC&quot;, -apple-system, BlinkMacSystemFont, Roboto, &quot;Helvetica Neue&quot;, Helvetica, Arial, &quot;Hiragino Sans GB&quot;, &quot;Source Han Sans&quot;, &quot;Noto Sans CJK Sc&quot;, &quot;Microsoft YaHei&quot;, &quot;Microsoft Jhenghei&quot;, sans-serif; font-size: 14px;\"><span style=\"background-color: rgb(255, 255, 255);\"></span><br /></span></p>',0,0),(15,2,'疑问解答','/user/qa',2,'/static/picture/5bff97ffcc002.png',1553052500,0,'疑问解答','<div><p>1.我在云计划平台上投资安全吗？<br />本平台采用多种资金管理措施，竭力保障用户的资金安全：&nbsp;1.专业第三方支付机构提供资金支付服务：公司委托专业的、具有支付业务资质第三方机构提供用户资金充值、取现等资金支付服务。&nbsp;2.唯一取现银行卡控制：用户在平台投资前须进行实名认证并绑定唯一一张属于本人的银行卡，投资本金收益仅可取现至该绑定银行卡中，从而保证平台资金封闭运行。&nbsp;3.全网站系统加密及保护技术：采用国际通用的系统加密及数据保护技术，保障用户在访问网站过程资金、密码等数据信息的安全&nbsp;4.资金管理内部控制严格：我们秉承专业金融机构的资金管理成熟经验和流程，实行严格的审核机制，以保障用户资金安全。云计划平台所有资金由银行进行监管，确保所有用户的资金安全。<br /><br /><br /><br />2.电子合同和股权证书是不是具有法律效应？</p><p>您好！根据《合同法》和《电子商务示范法》，在您点下投資按钮的时候就真实明确表达了您的投资意愿，所以您从网站上下载的合同具有法律效力。电子股权证书具有同等法律效力。</p><p><br /></p><p>3.在平台充值多久能到账？</p><p>平台充值审核时间是早上九点到晚上十二点，所有充值订单在三个小时内会审核通过。</p><p><br /></p><p>4.平台的提现时间和提现金额？</p><p>500元起就可以提现，提现时间是早上九点到晚上九点，所有提现24小时内到账。</p><p><br /></p><p><br /></p><p><br /></p><br /></div><div><br /></div>',1,0),(17,2,'联系我们','/user/concat',2,'/static/picture/5bff97ffcc002.png',1553137432,0,'云数E家客服李斌蝙蝠号：279700','<p></p><p>云计划客服李薇 畅聊ID：9286969&nbsp; 搜索添加好友，或者用畅聊APP扫码添加我的好友。&nbsp;&nbsp;</p><p>为了方便您联系我们，请务必添加我的畅聊ID，有疑问随时与我们联系。<br /></p><p><br /><br /></p><p><br /></p>',0,0),(18,2,'线下充值','/user/xianxiarec',2,'/static/picture/5bff97ffcc002.png',1553579012,0,'','<p><img src=\"/public/uploads/20190509/f993d8c8031e877ac1bbd091d884fb01.jpg\" alt=\"\" /><br /></p><p><br /></p>',0,0),(20,2,'安全保障','/detail/anquan',2,'/static/picture/5bff97ffcc002.png',1553588315,0,'','<span style=\"font-family: arial, 宋体, sans-serif; font-size: 14px; text-indent: 28px;\"></span>&nbsp; &nbsp;',0,0),(21,2,'支付宝','/user/zhifubaorec',2,'/static/picture/5bff97ffcc002.png',1556891864,0,'','<img src=\"/public/uploads/20190508/a032d4e5f18bc2d5587571e9709c943b.jpg\" alt=\"\" />',0,0),(22,2,'纪念币专区','/product/index/channel_id/22',5,'/static/picture/5bff97ffcc002.png',1624950749,0,'纪念币专区',NULL,0,0),(23,1,'关于我们','user/aboutus',2,'/public/uploads/20210905/3b9b7f37a71dd908368f3dbbf3fcd98e.png',1630822262,0,'','<p><img src=\"/public/uploads/20210908/13e04c22dbe30b361fdcab10f70acaf6.jpg\" alt=\"\" /><br /></p>',0,0),(25,1,'asdf','asdfsadfsadf',1,'/uploads/202201/20220129152043TYGYn.jpeg',1643440845,0,'asdfsadf','asdfasdfsadf',0,1643440845);
