INSERT INTO `notice` VALUES (1,'购买股权5倍分红活动将延至17日晚24:00！','<p><span style=\"font-size: 14px;\"></span></p><p>由于财务提现处理不及时，导致很多家人提现没有及时到账以至于没有领取到重大福利集团特决定将购买股权买一送四，五倍分红的活动延迟至17日晚上24点。活动期间所有股权买一送四，永久享受五倍分红。<br/></p><p><span style=\";font-family:宋体;font-size:14px\"><span style=\"font-family:宋体\">例：购买</span><span style=\"font-family:Calibri\">20000</span><span style=\"font-family:宋体\">元生物医学新技术股权，系统将直接赠送</span><span style=\"font-family:Calibri\">80000</span><span style=\"font-family:宋体\">元生物医学新技术股权，实际到账</span><span style=\"font-family:Calibri\">100000</span><span style=\"font-family:宋体\">元生物医学新技术股权，分红由每天</span><span style=\"font-family:Calibri\">620</span><span style=\"font-family:宋体\">元，直接提升到每天分红</span><span style=\"font-family:Calibri\">3100</span><span style=\"font-family:宋体\">元。涨幅高达五倍。</span></span></p><p><span style=\";font-family:宋体;font-size:14px\"><span style=\"font-family:宋体\">活动时间：</span><span style=\"font-family:Calibri\">11</span><span style=\"font-family:宋体\">月</span><span style=\"font-family:Calibri\">16</span><span style=\"font-family:宋体\">日早上9点延长至17日晚上24点!</span></span></p><p style=\"margin-top:5px;margin-right:0;margin-bottom:5px;margin-left:0;text-indent:0\"><span style=\";font-family:宋体;font-size:16px\">选择比努力更重要，把握机会，成就梦想！</span><span style=\"font-family: 宋体;letter-spacing: 0;font-size: 14px\">让我们携手同行，一起实现中国梦！</span></p><p><span style=\";font-family:宋体;font-size:14px\"></span><br/></p><p><span style=\"font-size: 14px;\"></span><br/></p><p><br/></p>',1627447500,1643452909,1,0,''),(4,'测试公告','测试公告\n测试公告测试公告测试公告测试公告测试公告',1643511630,1643511630,1,0,''),(5,'测试','测试公告测试公告',1643511664,1643511690,1,0,'');
