  `user_agent` varchar(256) NOT NULL DEFAULT '' COMMENT '浏览信息',
  `created` int unsigned NOT NULL DEFAULT '0' COMMENT '登录时间',
  `remark` varchar(20) NOT NULL DEFAULT '' COMMENT '备注',
